class Solution:
    def superPow(self, a: int, b: List[int]) -> int:
        MOD = 1337
        def pw(x, k):
            r = 1
            x %= MOD
            while k:
                if k & 1:
                    r = r * x % MOD
                x = x * x % MOD
                k >>= 1
            return r
        if not b:
            return 1
        return pw(self.superPow(a, b[:-1]), 10) * pw(a, b[-1]) % MOD

