class Solution {
public:
    int MOD = 1337;
    int pw(long long x, long long k) {
        int r = 1;
        x %= MOD;
        while (k) {
            if (k & 1) r = r * x % MOD;
            x = x * x % MOD;
            k >>= 1;
        }
        return r;
    }
    int superPow(int a, vector<int>& b) {
        if (b.empty()) return 1;
        int d = b.back();
        b.pop_back();
        long long p = superPow(a, b);
        b.push_back(d);
        return pw(p, 10) * pw(a, d) % MOD;
    }
};

