class Solution {
    private static final int MOD = 1337;
    private int pw(long x, long k) {
        int r = 1;
        x %= MOD;
        while (k > 0) {
            if ((k & 1) == 1) r = (int)(r * x % MOD);
            x = x * x % MOD;
            k >>= 1;
        }
        return r;
    }
    public int superPow(int a, int[] b) {
        return helper(a, b, b.length - 1);
    }
    private int helper(int a, int[] b, int i) {
        if (i < 0) return 1;
        return pw(helper(a, b, i - 1), 10) * pw(a, b[i]) % MOD;
    }
}

