class Solution {
    public int superPow(int a, int[] b) {
        final int MOD = 1337, PHI = 1140;
        long e = 0;
        for (int d : b) e = (e * 10 + d) % PHI;
        if (gcd(a, MOD) != 1 && e == 0) e = PHI;
        long r = 1, x = a % MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * x % MOD;
            x = x * x % MOD;
            e >>= 1;
        }
        return (int) r;
    }
    private long gcd(long x, long y) {
        while (y != 0) { long t = x % y; x = y; y = t; }
        return x;
    }
}

